INSERT INTO wimb.post_base (
       post_id
     , category_id
     , user_id
     , title
     , status
     , type
     , visibility
     , view_count
     , created_at
     , updated_at
)
VALUES (
       #{postId}
     , #{categoryId}
     , #{userId}
     , #{title}
     , #{status}
     , #{type}
     , #{visibility}
     , #{viewCount}
     , #{createdAt}
     , #{updatedAt}
)

INSERT INTO wimb.post_snippet (
       post_id
     , code
     , description
     , language
     , created_at
     , updated_at
)
VALUES (
       #{postId}
     , #{code}
     , #{description}
     , #{language}
     , #{createdAt}
     , #{updatedAt}
)

